// «Как проходит запись»: три шага с подсветкой статуса; статусы приходят из props,
// раскладка — вертикальный список на телефоне и неровная сетка на десктопе.
import { LazyMotion, domAnimation, m } from 'motion/react';
import { useReducedMotion } from 'motion/react';

type Step = { title: string; text: string; status?: string };

export type StepsBookingProps = {
  title: string;
  text?: string;
  steps: Step[];
};

const statusRing: Record<string, string> = {
  done: 'border-primary bg-primary text-primary-foreground',
  active: 'border-primary text-primary',
  idle: 'border-border bg-card text-card-foreground',
};

export default function StepsBooking({ title, text, steps }: StepsBookingProps) {
  const reduce = useReducedMotion();
  const animate = !reduce;

  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="max-w-text min-w-0">
          <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>
          {text ? <p className="mt-3 text-lead text-muted-foreground">{text}</p> : null}
        </div>

        <LazyMotion features={domAnimation}>
          <ol className="mt-10 grid gap-5 md:grid-cols-3 md:gap-6">
            {steps.map((step, i) => {
              const status = step.status ?? 'idle';
              return (
                <m.li
                  key={step.title}
                  {...(animate
                    ? { initial: { opacity: 0, y: 16 }, whileInView: { opacity: 1, y: 0 }, viewport: { once: true }, transition: { duration: 0.4, delay: i * 0.1 } }
                    : {})}
                  className={`min-w-0 rounded-lg border p-6 wrap-break-word ${statusRing[status]}`}
                >
                  <div className="flex items-center gap-3">
                    <span
                      className="inline-flex min-h-11 min-w-11 items-center justify-center rounded-control border border-current font-display text-h3 font-bold"
                      aria-hidden="true"
                    >
                      {i + 1}
                    </span>
                    {status === 'active' ? (
                      <span className="rounded-sm border border-current px-2 py-1 text-small font-semibold">
                        текущий шаг
                      </span>
                    ) : null}
                    {status === 'done' ? (
                      <span className="rounded-sm border border-current px-2 py-1 text-small font-semibold">
                        готово
                      </span>
                    ) : null}
                  </div>
                  <h3 className="mt-4 font-display text-h3 font-bold text-balance wrap-break-word">{step.title}</h3>
                  <p className="mt-2 text-body opacity-90">{step.text}</p>
                </m.li>
              );
            })}
          </ol>
        </LazyMotion>
      </div>
    </section>
  );
}

