// «Как проходит запись»: три шага с подсветкой статуса; статусы приходят из props,
// раскладка — вертикальный список на телефоне и неровная сетка на десктопе.
import { LazyMotion, domAnimation, m } from 'motion/react';
import { useReducedMotion } from 'motion/react';

type Step = { title: string; text: string; status?: string };

export type StepsBookingProps = {
  title: string;
  text?: string;
  steps: Step[];
};

const statusRing: Record<string, string> = {
  done: 'border-primary bg-primary text-primary-foreground',
  active: 'border-primary text-primary',
  idle: 'border-border bg-card text-card-foreground',
};

export default function StepsBooking({ title, text, steps }: StepsBookingProps) {
  const reduce = useReducedMotion();
  const animate = !reduce;

  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="max-w-text min-w-0">
          <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>
          {text ? <p className="mt-3 text-lead text-muted-foreground">{text}</p> : null}
        </div>

        <LazyMotion features={domAnimation}>
          <ol className="mt-10 grid gap-5 md:grid-cols-3 md:gap-6">
            {steps.map((step, i) => {
              const status = step.status ?? 'idle';
              return (
                <m.li
                  key={step.title}
                  {...(animate
                    ? { initial: { opacity: 0, y: 16 }, whileInView: { opacity: 1, y: 0 }, viewport: { once: true }, transition: { duration: 0.4, delay: i * 0.1 } }
                    : {})}
                  className={`min-w-0 rounded-lg border p-6 wrap-break-word ${statusRing[status]}`}
                >
                  <div className="flex items-center gap-3">
                    <span
                      className="inline-flex min-h-11 min-w-11 items-center justify-center rounded-control border border-current font-display text-h3 font-bold"
                      aria-hidden="true"
                    >
                      {i + 1}
                    </span>
                    {status === 'active' ? (
                      <span className="rounded-sm border border-current px-2 py-1 text-small font-semibold">
                        текущий шаг
                      </span>
                    ) : null}
                    {status === 'done' ? (
                      <span className="rounded-sm border border-current px-2 py-1 text-small font-semibold">
                        готово
                      </span>
                    ) : null}
                  </div>
                  <h3 className="mt-4 font-display text-h3 font-bold text-balance wrap-break-word">{step.title}</h3>
                  <p className="mt-2 text-body opacity-90">{step.text}</p>
                </m.li>
              );
            })}
          </ol>
        </LazyMotion>
      </div>
    </section>
  );
}

// «Как проходит запись»: вертикальная доминанта-лента шагов с подсветкой статуса;
// статусы приходят из props, час берётся из расписания записи.
import { LazyMotion, domAnimation, m } from 'motion/react';
import { useReducedMotion } from 'motion/react';

type Step = { title: string; text: string; status?: string };

export type StepsBookingProps = {
  title: string;
  text?: string;
  steps: Step[];
};

export default function StepsBooking({ title, text, steps }: StepsBookingProps) {
  const reduce = useReducedMotion();
  const animate = !reduce;

  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="grid gap-10 lg:grid-cols-[1fr_1.4fr] lg:gap-16">
          <div className="max-w-text min-w-0">
            <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>
            {text ? <p className="mt-4 text-lead text-muted-foreground">{text}</p> : null}
            <a
              href="/booking#form"
              className="mt-8 inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-6 text-center text-body font-bold text-primary-foreground transition-opacity duration-200 hover:opacity-90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary"
            >
              Открыть форму записи
            </a>
          </div>

          <LazyMotion features={domAnimation}>
            <ol className="relative flex min-w-0 flex-col gap-4">
              {steps.map((step, i) => {
                const status = step.status ?? 'idle';
                const done = status === 'done';
                const active = status === 'active';
                return (
                  <m.li
                    key={step.title}
                    {...(animate
                      ? { initial: { opacity: 0, y: 16 }, whileInView: { opacity: 1, y: 0 }, viewport: { once: true }, transition: { duration: 0.4, delay: i * 0.1 } }
                      : {})}
                    className={`flex min-w-0 items-start gap-5 rounded-lg border p-5 wrap-break-word ${
                      done
                        ? 'border-primary bg-primary text-primary-foreground'
                        : active
                          ? 'border-primary bg-card text-card-foreground'
                          : 'border-border bg-card text-card-foreground'
                    }`}
                  >
                    <span
                      className="inline-flex min-h-11 min-w-11 shrink-0 items-center justify-center rounded-control border border-current font-display text-h3 font-bold"
                      aria-hidden="true"
                    >
                      {i + 1}
                    </span>
                    <div className="min-w-0">
                      <div className="flex flex-wrap items-center gap-x-3 gap-y-1">
                        <h3 className="font-display text-h3 font-bold text-balance wrap-break-word">{step.title}</h3>
                        {done ? (
                          <span className="rounded-sm border border-current px-2 py-0.5 text-small font-semibold">готово</span>
                        ) : null}
                        {active ? (
                          <span className="rounded-sm border border-current px-2 py-0.5 text-small font-semibold">текущий шаг</span>
                        ) : null}
                      </div>
                      <p className={`mt-2 text-body ${done ? '' : 'text-muted-foreground'}`}>{step.text}</p>
                    </div>
                  </m.li>
                );
              })}
            </ol>
          </LazyMotion>
        </div>
      </div>
    </section>
  );
}

// «Как проходит запись»: текстовая лента шагов (номер-кикер, заголовок, строка описания)
// с вертикальной направляющей и подсветкой статуса из props.
import { LazyMotion, domAnimation, m } from 'motion/react';
import { useReducedMotion } from 'motion/react';

type Step = { hint: string; title: string; text: string; status?: string };

export type StepsBookingProps = {
  title: string;
  text?: string;
  steps: Step[];
};

export default function StepsBooking({ title, text, steps }: StepsBookingProps) {
  const reduce = useReducedMotion();
  const animate = !reduce;

  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="grid gap-10 lg:grid-cols-[1fr_1.4fr] lg:gap-16">
          <div className="max-w-text min-w-0">
            <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>
            {text ? <p className="mt-4 text-lead text-muted-foreground">{text}</p> : null}
            <a
              href="/booking#form"
              className="mt-8 inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-6 text-center text-body font-bold text-primary-foreground transition-opacity duration-200 hover:opacity-90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary"
            >
              Открыть форму записи
            </a>
          </div>

          <LazyMotion features={domAnimation}>
            <ol className="relative flex min-w-0 flex-col border-l border-border pl-6">
              {steps.map((step, i) => {
                const status = step.status ?? 'idle';
                const done = status === 'done';
                const active = status === 'active';
                return (
                  <m.li
                    key={step.title}
                    {...(animate
                      ? { initial: { opacity: 0, x: 16 }, whileInView: { opacity: 1, x: 0 }, viewport: { once: true }, transition: { duration: 0.4, delay: i * 0.1 } }
                      : {})}
                    className={`relative pb-8 last:pb-0 ${active ? 'rounded-md' : ''}`}
                  >
                    <span
                      aria-hidden="true"
                      className={`absolute -left-[31px] top-1.5 h-2.5 w-2.5 rounded-sm border ${
                        done ? 'border-primary bg-primary' : active ? 'border-primary bg-background' : 'border-border bg-background'
                      }`}
                    />
                    <p
                      className={`text-small font-semibold tracking-wide uppercase ${
                        done ? 'text-primary' : active ? 'text-primary' : 'text-muted-foreground'
                      }`}
                    >
                      {step.hint}
                      {done ? ' — готово' : ''}
                      {active ? ' — текущий шаг' : ''}
                    </p>
                    <h3 className="mt-1 font-display text-h3 font-bold text-balance wrap-break-word">{step.title}</h3>
                    <p className="mt-1 text-body text-muted-foreground wrap-break-word">{step.text}</p>
                  </m.li>
                );
              })}
            </ol>
          </LazyMotion>
        </div>
      </div>
    </section>
  );
}

